@push('scripts')<script>(function(){var project=document.getElementById('launch-project'),system=document.getElementById('launch-system'),emailWrap=document.getElementById('launch-email-wrap'),email=document.getElementById('launch-email'),all=[].slice.call(system.querySelectorAll('option[data-project]'));function syncSystems(){var p=project.value,current=system.value;all.forEach(function(o){o.hidden=o.dataset.project!==p;o.disabled=o.hidden;});if(!all.some(function(o){return !o.disabled&&o.value===current;}))system.value='';syncEmail();}function syncEmail(){var o=system.options[system.selectedIndex],needed=o&&o.dataset.shopline==='1';emailWrap.style.display=needed?'block':'none';email.required=needed;if(!needed)email.value='';}project.addEventListener('change',syncSystems);system.addEventListener('change',syncEmail);var op=document.getElementById('launch-operator');if(op)op.addEventListener('change',function(){location.href=this.dataset.url+'?operator_user_id='+encodeURIComponent(this.value);});syncSystems();})();</script>@endpush
